2. 수정 방안:
```typescript
// 버그 수정 예시
export function useScheduleGridStatistics(
  employees: Ref<Employee[]>,
  dates: Ref<GridColumn[]>,
  assignments: Ref<AssignmentMap>
) {
  // Deep watch로 중첩 객체 변경 감지
  const rowStats = computed(() => {
    const stats: Record<string, RowStat> = {};

    for (const emp of employees.value) {
      const empAssignments = assignments.value[emp.id] || {};
      const stat: RowStat = { D: 0, E: 0, N: 0, total: 0 };

      for (const date of dates.value) {
        const shift = empAssignments[date.date];

        // 빈 셀 및 O 처리
        if (!shift || shift === 'O') continue;

        if (shift === 'D') stat.D++;
        else if (shift === 'E') stat.E++;
        else if (shift === 'N') stat.N++;

        stat.total++;
      }

      stats[emp.id] = stat;
    }

    return stats;
  });

